LogicDefinition.ScriptText:
#load "reference"

//////////////////////////////////////////////////////////////////////////////////////////////////////////////
//                                                                                                          //
//    Logik:           Auflagekontrolle                                                                     //
//                                                                                                          //
//////////////////////////////////////////////////////////////////////////////////////////////////////////////
//
//    Datum            Version        Autor            Beschreibung
//
//    N.N.             1.1.0          Nusser           Urversion ohne Differenzdruckschalter
//    N.N.             1.3.1          Gaugler          Funktion für Differenzdruckschalter und Parameternamen angepasst
//    N.N.             1.3.2          Egg              Logik vereinfacht
//    N.N.             1.5.1          Gaugler          NIO-Fall ergänzt
//    N.N.             1.5.2          Nusser           Differenzdruck = false bei ausgeschalteter Versorgung
//    23.05.2025       1.6.0          Greif            Header integriert
//
//============================================================================================================
//
//    SW-Standard      Geprüft        Prüfer           Allgemeine Informationen
//                     
//    FEE              x              Greif            Verhaltensmodell für 4 Auflagenkontrollen mit Differenzdruckschalter
/*
//============================================================================================================
//
//    Beschreibung:
//
//    Die Logik dient als Druckkontrolle, sie überwacht bis zu 4 Drucksensoren.
//    Über den Eingang (PLC_EinspeisungEinschalten=1) wird die Logik aktiviert und
//    das Bit (PLC_IN_EinspeisedruckOk_X) gesetzt.
//    Nur wenn die Sensoren (SIM_Sensor_X=1) und (SIM_AuflagenkontrolleNio_X=0) schalten, 
//    wird der Diffferenzdruck Ok ausgegeben.
//
//============================================================================================================
//
//    Input Slot Values
//    PLC_EinspeisungEinschalten        =   Bool, zum Einschalten der Logik
//    SIM_Sensor_1-4                    =   Bool, Sensor zur Drucküberwachung
//    SIM_AuflagenkontrolleNio_1-4      =   Bool, Auflagekontrolle Nio
//
//    Output Slot Values
//    PLC_DifferenzdruckOk_1-4          =   Bool, Ausgabe Differenzdruck Ok
//    PLC_EinspeisedruckOk_1-4          =   Bool, Ausgabe Einspeisedruck Ok
//
//============================================================================================================
*/
//////////////////////////////////////////////////////////////////////////////////////////////////////////////

#region Einspeisedruck/ Differenzdruck setzen
//============================================================================================================
// E I N S P E I S E D R U C K  /  D I F F E R E N Z D R U C K    S E T Z E N
//============================================================================================================

if (PLC_EinspeisungEinschalten)
{
    // Einspeisedruck Ok setzen
    PLC_IN_EinspeisedruckOk_1 = true;
    PLC_IN_EinspeisedruckOk_2 = true;
    PLC_IN_EinspeisedruckOk_3 = true;
    PLC_IN_EinspeisedruckOk_4 = true;

    // Differenzdruck Ok 
    PLC_IN_DifferenzdruckOk_1 = SIM_Sensor_1 && !SIM_AuflagenkontrolleNio_1;    
    PLC_IN_DifferenzdruckOk_2 = SIM_Sensor_2 && !SIM_AuflagenkontrolleNio_2;
    PLC_IN_DifferenzdruckOk_3 = SIM_Sensor_3 && !SIM_AuflagenkontrolleNio_3;
    PLC_IN_DifferenzdruckOk_4 = SIM_Sensor_4 && !SIM_AuflagenkontrolleNio_4;
}

else
{
    // Einspeisedruck Ok zurücksetzen
    PLC_IN_EinspeisedruckOk_1 = false;
    PLC_IN_EinspeisedruckOk_2 = false;
    PLC_IN_EinspeisedruckOk_3 = false;
    PLC_IN_EinspeisedruckOk_4 = false;

    // Differenzdruck Ok zurücksetzen  
    PLC_IN_DifferenzdruckOk_1 = false;
    PLC_IN_DifferenzdruckOk_2 = false; 
    PLC_IN_DifferenzdruckOk_3 = false;
    PLC_IN_DifferenzdruckOk_4 = false;
}
#endregion
